#!/usr/bin/env python3
from pathlib import Path
import re, sys
root=Path(sys.argv[1] if len(sys.argv)>1 else "game")
script=root/"scripts"/"art"/"d2d29_minimal_token_runtime.gd"
if not script.exists():
    raise SystemExit("D2D.64 requires D2D.63 runtime")
s=script.read_text(encoding="utf-8")
if 'title.text = "D2D.63 FEMALE HEAD ONLY:"' not in s:
    raise SystemExit("D2D.64 title anchor missing")
s=s.replace('title.text = "D2D.63 FEMALE HEAD ONLY:"','title.text = "D2D.64 FEMALE HEAD ONLY:"',1)

s,n=re.subn(r'const FEMALE_HEAD_B64 := "[^"]+"',
            'const FEMALE_HEAD_B64 := ""',s,count=1)
if n!=1:
    raise SystemExit("D2D.64 head constant missing")

# Re-load after all previous patches so the female texture is guaranteed valid.
anchor='''    tex_head_female = _texture_from_embedded_png(FEMALE_HEAD_B64)
'''
if anchor not in s:
    raise SystemExit("D2D.64 loader anchor missing")
s=s.replace(anchor,anchor+'    assert(tex_head_female != null, "D2D.64 female head texture failed to decode")\n',1)

script.write_text(s,encoding="utf-8")

ep=root/"export_presets.cfg"
e=ep.read_text(encoding="utf-8")
e,n1=re.subn(r'(?m)^version/code=\d+$','version/code=137',e,count=1)
e,n2=re.subn(r'(?m)^version/name="[^"]*"$','version/name="0.21.0D2D.64"',e,count=1)
if n1!=1 or n2!=1:
    raise SystemExit("D2D.64 version anchors missing")
ep.write_text(e,encoding="utf-8")

sm=root/"scripts/save/save_manager.gd"
if sm.exists():
    t=sm.read_text(encoding="utf-8")
    t=re.sub(r'const GAME_VERSION := "[^"]+"','const GAME_VERSION := "0.21.0D2D.64"',t,count=1)
    sm.write_text(t,encoding="utf-8")
print("Applied D2D.64 head-only valid 64x64 female PNG cutout.")
